try{global.gc();const run=await guarded({site:s.website,dir,command:'--max-old-space-size=1024 --experimental-strip-types --test --test-reporter=tap --test-concurrency=1 '+roots.join(' '),heap:1024,aggregate:2048,minimum:4096,extraEnv:{VM_WEBSITE_ROOT:s.website,VM_ATLAS_SOURCE_REPO:s.atlas,ATLAS_SOURCE_REPO:s.atlas,VM_CURRENT_SOURCE_RECEIPT:sf,VM_CURRENT_SOURCE_SHA256:hash(sf)}});verify();const log=fs.readFileSync(dir+'/runner.stdout.log','utf8'),counts=Object.fromEntries(['tests','pass','fail','cancelled','skipped','todo'].map(k=>[k,Number([...log.matchAll(new RegExp('^# '+k+' (\\d+)','gm'))].at(-1)?.[1]??-1)]));const result={at:new Date().toISOString(),source:{path:sf,sha256:hash(sf)},roots,run,counts,allSourceUnchanged:true,normalPreviewChanged:false};fs.writeFileSync(base+'/RESULT.json',JSON.stringify(result,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({result:base+'/RESULT.json',sha256:hash(base+'/RESULT.json'),counts,passing:run.passing}));}finally{process.removeListener('exit',early);retire();}
